    {"reference_id": "R1", "candidate_id": "C1", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "No rolling hills as specified in the prompt", "candidate_evidence": "The crest feathers on the peacock's head briefly dissolve, distort, and flicker unnaturally around 1-2 seconds.", "basis": "explicit_separation", "reason_ko": "기준 제기는 프롬프트에 명시된 완만한 언덕(rolling hills)이 존재하지 않는다는 환경 요소 누락 문제인 반면, 후보는 공작새 머리 볏 깃털의 일시적 왜곡 및 깜빡임을 지적하고 있어 문제의 대상(엔티티)과 현상이 완전히 상이합니다.", "separation_basis": "different_entity"},
    {"reference_id": "R1", "candidate_id": "C2", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "No rolling hills as specified in the prompt", "candidate_evidence": "The peacock's train feathers elongate rapidly and spawn additional eye-patterns unnaturally as the camera moves.", "basis": "explicit_separation", "reason_ko": "기준 제기는 지형 요소(언덕)의 부재를 문제 삼고 있으나, 후보는 공작새 꼬리 깃털이 비정상적으로 늘어나고 무늬가 증식하는 변형 현상을 다루므로 대상 엔티티가 명확히 분리됩니다.", "separation_basis": "different_entity"},
    {"reference_id": "R1", "candidate_id": "C3", "target_relation": "different", "reference_claim_ids": ["R1.S1"], "reference_evidence": "No rolling hills as specified in the prompt", "candidate_evidence": "The crest feathers on the peacock's head distort, flatten, and partially fade or change shape as the bird turns its head.", "basis": "explicit_separation", "reason_ko": "기준 제기는 프롬프트에 제시된 완만한 언덕의 미생성을 지적하는 반면, 후보는 공작새 머리 볏 깃털의 왜곡 및 형태 변화를 설명하므로 서로 다른 대상에 관한 명확히 분리된 불만입니다.", "separation_basis": "different_entity"},
    {"reference_id": "R1", "candidate_id": "C4", "target_relation": "different", "reference_claim_ids": ["R1.S2"], "reference_evidence": "or streams as well", "candidate_evidence": "The leg movement exhibits unnatural sliding and slight structural warping relative to the ground leaves.", "basis": "explicit_separation", "reason_ko": "기준 제기는 개울(streams)과 같은 배경 환경 요소의 누락에 관한 지적인 반면, 후보는 공작새 다리의 미끄러짐 및 구조적 뒤틀림 현상을 설명하고 있어 문제의 대상과 발생 현상이 서로 완전히 다릅니다.", "separation_basis": "different_entity"}
  ]
}

